import bisect

def lis_length(nums: list[int]) -> int:
    """Compute length of longest increasing subsequence in O(N log N)."""
    tails: list[int] = []
    for x in nums:
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
